# wlanpi-netviews version 3.0.6
import sys
import importlib.abc

DEST_DIR = "/opt/wlanpi-webui/lib/python3.13/site-packages/wlanpi_webui/static/img"
DEST_IMG = DEST_DIR + "/fpms_latest.png"
TMP_IMG  = DEST_IMG + ".tmp"
VER_FILE = DEST_DIR + "/fpms_latest.version"
NAV_FIFO = "/run/wlanpi-netviews.fifo"

OLED_TARGET     = "fpms.modules.wlanpi_oled"
PAGE_TARGET     = "fpms.modules.pages.page"
HOMEPAGE_TARGET = "fpms.modules.pages.homepage"

LOG_FILE = "/tmp/wlanpi_netviews.log"

def _log(msg):
    import time
    try:
        with open(LOG_FILE, "a") as f:
            f.write(f"{time.strftime('%H:%M:%S')} {msg}\n")
    except Exception:
        pass

_log("hook module loaded")

# Shared nav state — populated by _patch_page on each draw_page call.
# Keyed so the reader thread can pick them up without needing early imports.
_nav_ctx = {'g_vars': None, 'menu': None}

KEY_MAP = {
    'w': 'up',    '8': 'up',
    'x': 'down',  '2': 'down',
    'a': 'left',  '4': 'left',
    'd': 'right', '6': 'right',
    's': 'center','5': 'center',
    'i': 'key1',  '*': 'key1',
    'o': 'key2',  '-': 'key2',
    'p': 'key3',  '+': 'key3',
}


class _NetviewsFinder(importlib.abc.MetaPathFinder):

    def find_spec(self, fullname, path, target=None):
        if fullname not in (OLED_TARGET, PAGE_TARGET, HOMEPAGE_TARGET):
            return None
        for finder in sys.meta_path:
            if finder is self:
                continue
            try:
                spec = finder.find_spec(fullname, path, target)
            except AttributeError:
                continue
            if spec is not None:
                _log(f"intercepting {fullname}")
                spec.loader = _PatchingLoader(spec.loader, fullname)
                return spec
        return None


class _PatchingLoader(importlib.abc.Loader):
    def __init__(self, real_loader, target_name):
        self._real = real_loader
        self._name = target_name

    def create_module(self, spec):
        return self._real.create_module(spec)

    def exec_module(self, module):
        self._real.exec_module(module)
        if self._name == OLED_TARGET:
            _patch_oled(module)
        elif self._name == PAGE_TARGET:
            _patch_page(module)
        elif self._name == HOMEPAGE_TARGET:
            _patch_homepage(module)


def _patch_oled(oled):
    import os
    os.makedirs(DEST_DIR, exist_ok=True)

    _orig = oled.drawImage

    def _drawImage(image):
        _orig(image)
        try:
            image.save(TMP_IMG, format="PNG")
            os.replace(TMP_IMG, DEST_IMG)
            import time
            with open(VER_FILE, "w") as f:
                f.write(str(int(time.time() * 1000)))
        except Exception:
            pass

    oled.drawImage = _drawImage


def _patch_page(page_mod):
    _log(f"_patch_page called on {page_mod}")
    _orig_draw = page_mod.Page.draw_page

    def _draw_page(self, g_vars, menu):
        # Keep nav context current on every draw so the reader always has live refs.
        _nav_ctx['g_vars'] = g_vars
        _nav_ctx['menu'] = menu
        return _orig_draw(self, g_vars, menu)

    page_mod.Page.draw_page = _draw_page
    _log("Page.draw_page patched OK")


def _patch_homepage(homepage_mod):
    _log(f"_patch_homepage called on {homepage_mod}")
    _orig_home = homepage_mod.HomePage.home_page

    def _home_page(self, g_vars, menu):
        # HomePage.home_page is called every ~2s from the main loop.
        # Grab g_vars and menu here so _nav() has them immediately.
        _nav_ctx['g_vars'] = g_vars
        _nav_ctx['menu']   = menu
        return _orig_home(self, g_vars, menu)

    homepage_mod.HomePage.home_page = _home_page
    _log("HomePage.home_page patched OK")


def _nav(direction):
    _log(f"_nav called: direction={direction}")
    g_vars = _nav_ctx['g_vars']
    menu   = _nav_ctx['menu']
    if g_vars is None or menu is None:
        _log("SKIP: g_vars or menu is None")
        return
    state = {k: g_vars.get(k) for k in ('disable_keys','shutdown_in_progress','sig_fired','drawing_in_progress','screen_cleared','display_state','start_up')}
    _log(f"g_vars flags: {state}")
    if g_vars.get('disable_keys') or g_vars.get('shutdown_in_progress'):
        _log("SKIP: disable_keys or shutdown_in_progress")
        return
    if g_vars.get('sig_fired') or g_vars.get('drawing_in_progress'):
        _log("SKIP: sig_fired or drawing_in_progress")
        return
    try:
        from fpms.modules.constants import PAGE_SLEEP
        from fpms.modules.nav.buttons import Button
    except Exception as e:
        _log(f"SKIP: import failed: {e}")
        return
    g_vars['start_up'] = False
    g_vars['pageSleepCountdown'] = PAGE_SLEEP
    g_vars['button_press_count'] = g_vars.get('button_press_count', 0) + 1
    if g_vars.get('screen_cleared'):
        import fpms.modules.wlanpi_oled as oled
        oled.wakeup()
        g_vars['screen_cleared'] = False
        _log("woke screen from sleep")
        return
    g_vars['sig_fired'] = True
    try:
        _log(f"calling Button.menu_{direction}()")
        btn = Button(g_vars, menu)
        if   direction == 'up':     btn.menu_up(g_vars, menu)
        elif direction == 'down':   btn.menu_down(g_vars, menu)
        elif direction == 'left':   btn.menu_left(g_vars, menu)
        elif direction == 'right':  btn.menu_right(g_vars, menu)
        elif direction == 'center': btn.menu_center(g_vars, menu)
        elif direction == 'key1':
            shortcuts = [
                _create_shortcut(menu, ["Utils",   "Reachability"]),
                _create_shortcut(menu, ["Network", "LLDP Neighbour"]),
                _create_shortcut(menu, ["Network", "Eth0 IP Config"]),
            ]
            option_selected = g_vars['option_selected']
            option_index = 0
            option_found = False
            if g_vars['display_state'] == 'page':
                for i, sc in enumerate(shortcuts):
                    if sc and option_selected == sc[-1]:
                        option_found = True
                        option_index = i
                        break
            next_index = (option_index + 1) % len(shortcuts) if option_found else 0
            btn.shortcut(g_vars, menu, shortcuts[next_index])
        elif direction == 'key2':
            shortcut = _create_shortcut(menu, ["Mode", "Classic Mode"])
            if g_vars.get('current_mode') == "classic":
                shortcut = _create_shortcut(menu, ["Modes", "Hotspot"])
            btn.shortcut(g_vars, menu, shortcut)
        elif direction == 'key3':
            reboot_shortcut   = _create_shortcut(menu, ["System", "Reboot"])
            shutdown_shortcut = _create_shortcut(menu, ["System", "Shutdown"])
            next_shortcut = reboot_shortcut
            if g_vars['current_menu_location'][:-1] == reboot_shortcut:
                next_shortcut = shutdown_shortcut
            btn.shortcut(g_vars, menu, next_shortcut)
        _log(f"Button.menu_{direction}() returned OK")
    except Exception as e:
        import traceback
        _log(f"Button.menu_{direction}() EXCEPTION: {e}\n{traceback.format_exc()}")
    finally:
        g_vars['sig_fired'] = False


def _create_shortcut(menu, path):
    import types
    if isinstance(menu, types.FunctionType):
        if len(path) > 0:
            raise Exception("invalid path")
        return [menu]
    if len(path) > 0:
        for index, item in enumerate(menu):
            if item["name"] == path[0]:
                return [index] + _create_shortcut(item["action"], path[1:])
    return []


def _start_fifo_reader():
    import threading

    def _fifo_reader():
        _log("fifo reader thread started")
        while True:
            try:
                with open(NAV_FIFO, 'r') as f:
                    for char in iter(lambda: f.read(1), ''):
                        _log(f"fifo read char: {repr(char)}")
                        direction = KEY_MAP.get(char)
                        if direction:
                            _nav(direction)
            except Exception as e:
                _log(f"fifo reader exception: {e}")
                import time
                time.sleep(0.5)

    t = threading.Thread(target=_fifo_reader, name="netviews-nav", daemon=True)
    t.start()
    _log("fifo reader thread launched")


sys.meta_path.insert(0, _NetviewsFinder())

# Create FIFO and start the reader thread immediately at fpms startup.
import os as _os
try:
    if not _os.path.exists(NAV_FIFO):
        _os.mkfifo(NAV_FIFO)
    _os.chmod(NAV_FIFO, 0o666)
except Exception:
    pass

_start_fifo_reader()